
const perguntas = [
    {
            pergunta: "1. Qual é a profissão de Jão?",
                    alternativas: [
                                "Ator de novelas",
                                            "Cantor e compositor",
                                                        "Jogador de futebol",
                                                                    "Apresentador de TV"
                                                                            ],
                                                                                    correta: 1,
                                                                                            explicacao: "Isso mesmo! Jão é cantor e compositor brasileiro."
                                                                                                },
                                                                                                    {
                                                                                                            pergunta: "2. Qual foi o álbum de estreia de Jão?",
                                                                                                                    alternativas: [
                                                                                                                                "Pirata",
                                                                                                                                            "Super",
                                                                                                                                                        "Lobos",
                                                                                                                                                                    "Anti-Herói"
                                                                                                                                                                            ],
                                                                                                                                                                                    correta: 2,
                                                                                                                                                                                            explicacao: "Acertou! Lobos foi lançado em 2018."
                                                                                                                                                                                                },
                                                                                                                                                                                                    {
                                                                                                                                                                                                            pergunta: "3. Em que ano o álbum Pirata foi lançado?",
                                                                                                                                                                                                                    alternativas: [
                                                                                                                                                                                                                                "2018",
                                                                                                                                                                                                                                            "2019",
                                                                                                                                                                                                                                                        "2021",
                                                                                                                                                                                                                                                                    "2023"
                                                                                                                                                                                                                                                                            ],
                                                                                                                                                                                                                                                                                    correta: 2,
                                                                                                                                                                                                                                                                                            explicacao: "Perfeito! Pirata foi lançado em 2021."
                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                            pergunta: "4. Qual destes álbuns foi lançado em 2023?",
                                                                                                                                                                                                                                                                                                                    alternativas: [
                                                                                                                                                                                                                                                                                                                                "Lobos",
                                                                                                                                                                                                                                                                                                                                            "Super",
                                                                                                                                                                                                                                                                                                                                                        "Anti-Herói",
                                                                                                                                                                                                                                                                                                                                                                    "Pirata"
                                                                                                                                                                                                                                                                                                                                                                            ],
                                                                                                                                                                                                                                                                                                                                                                                    correta: 1,
                                                                                                                                                                                                                                                                                                                                                                                            explicacao: "Isso aí! Super foi lançado em 2023."
                                                                                                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                                                                                            pergunta: "5. Qual destes temas aparece nas músicas de Jão?",
                                                                                                                                                                                                                                                                                                                                                                                                                    alternativas: [
                                                                                                                                                                                                                                                                                                                                                                                                                                "Somente esportes",
                                                                                                                                                                                                                                                                                                                                                                                                                                            "Apenas notícias políticas",
                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Amor e sentimentos",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Somente receitas"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    correta: 2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            explicacao: "Correto! Amor e sentimentos são temas recorrentes em suas músicas."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let indiceAtual = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let pontos = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let respondeu = false;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const elementoPergunta = document.getElementById("pergunta");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const elementoAlternativas = document.getElementById("alternativas");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const elementoFeedback = document.getElementById("feedback");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const elementoProgresso = document.getElementById("progresso");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const elementoPontuacao = document.getElementById("pontuacao");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const barraProgresso = document.getElementById("barra-progresso");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const botaoProximo = document.getElementById("proximo");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const botaoReiniciar = document.getElementById("reiniciar");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function mostrarPergunta() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    respondeu = false;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const atual = perguntas[indiceAtual];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            elementoPergunta.textContent = atual.pergunta;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                elementoAlternativas.innerHTML = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    elementoFeedback.textContent = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botaoProximo.hidden = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botaoReiniciar.hidden = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                elementoProgresso.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `PERGUNTA ${indiceAtual + 1} DE ${perguntas.length}`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            elementoPontuacao.textContent = `Pontos: ${pontos}`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                barraProgresso.style.width =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `${(indiceAtual / perguntas.length) * 100}%`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            atual.alternativas.forEach((alternativa, indice) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const botao = document.createElement("button");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botao.className = "alternativa";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    botao.textContent = alternativa;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botao.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        verificarResposta(indice, botao);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        elementoAlternativas.appendChild(botao);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function verificarResposta(indiceEscolhido, botaoEscolhido) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (respondeu) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    respondeu = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const atual = perguntas[indiceAtual];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const botoes = elementoAlternativas.querySelectorAll("button");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const acertou = indiceEscolhido === atual.correta;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    botoes.forEach((botao, indice) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botao.disabled = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (indice === atual.correta) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                botao.classList.add("correta");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (acertou) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pontos++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                elementoFeedback.textContent = "🎉 " + atual.explicacao;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botaoEscolhido.classList.add("correta");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    elementoFeedback.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "💡 Não foi dessa vez! " + atual.explicacao;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botaoEscolhido.classList.add("errada");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                elementoPontuacao.textContent = `Pontos: ${pontos}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    barraProgresso.style.width =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `${((indiceAtual + 1) / perguntas.length) * 100}%`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (indiceAtual < perguntas.length - 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botaoProximo.hidden = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    finalizarJogo();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function finalizarJogo() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            elementoPergunta.textContent = "DESAFIO CONCLUÍDO! 🎤";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                elementoProgresso.textContent = "RESULTADO FINAL";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    barraProgresso.style.width = "100%";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let mensagem;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (pontos === 5) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mensagem = "Incrível! Você conhece muito o universo de Jão!";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else if (pontos >= 3) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mensagem = "Mandou bem! Você conhece bastante sobre Jão.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mensagem = "Continue explorando a discografia e tente novamente!";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    elementoFeedback.textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `${mensagem} Você fez ${pontos} de ${perguntas.length} pontos.`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                elementoAlternativas.innerHTML = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    botaoProximo.hidden = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botaoReiniciar.hidden = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botaoProximo.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (indiceAtual < perguntas.length - 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    indiceAtual++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mostrarPergunta();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                botaoReiniciar.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    indiceAtual = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pontos = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            respondeu = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mostrarPergunta();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mostrarPergunta();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                